Lemma ctx_scalars_refl c :
  0 <= c_mmap_counter c < 2^32 -> 0 <= c_seq c < 256 ->
  (forall i v, c_bounces c !! i = Some v -> 0 <= i < 32 /\ 0 <= v < 256) ->
  (forall i v, c_unmap_seq c !! i = Some v -> 0 <= i < 32 /\ 0 <= v < 256) ->
  ctx_scalars_eq c c.
